ruleSearch.bookList:
@js:(function(){
function lineBase(){var S=null;try{if(typeof source!=='undefined'&&source)S=source}catch(e){}
 if(!S){try{S=java}catch(e){}}var v='';try{if(S)v=String(S.get('bp_line')||'')}catch(e){}
 if(!v||v=='null'||v=='undefined')v='https://www.blpopo.vip';return String(v).replace(/\/+$/,'')}
function parse(h){var out=new Packages.java.util.ArrayList();try{var d=Packages.org.jsoup.Jsoup.parse(String(h));
 var lis=d.select('.slist ul li');
 for(var i=0;i<lis.size();i++){var as=lis.get(i).select('a');if(as.size()<3)continue;
  var href=String(as.get(1).attr('href')||'');var m=/\/book\/(\d+)\.html/.exec(href);if(!m)continue;
  var id=m[1];var p=id.length>=5?id.substring(0,2):'0';
  out.add(JSON.stringify({name:as.get(1).text(),author:as.get(2).text(),kind:'',
   bookUrl:B+m[0],coverUrl:'https://img.blpopo.vip/image/'+p+'/'+id+'/'+id+'s.jpg'}))}}catch(e){}
 return out}
var B=lineBase();var k='';
var bu='';try{bu=String(typeof baseUrl!=='undefined'?baseUrl:'')}catch(e){}
var qm=/[?&]q=([^&]*)/.exec(bu);
if(qm){try{k=decodeURIComponent(qm[1].replace(/\+/g,' '))}catch(e){k=qm[1]}}
else{try{k=String(typeof key!=='undefined'?key:'')}catch(e){}}
var opt=JSON.stringify({method:'POST',body:'s='+k+'&type=articlename&submit=',charset:'gbk',timeout:12000});
var h='';try{h=String(java.ajax(B+'/s.php,'+opt))}catch(e){}
if(h.indexOf('class="blue"')<0&&B.indexOf('blpopo.vip')<0){try{h=String(java.ajax('https://blpopo.vip/s.php,'+opt))}catch(e2){}}
if(h.indexOf('class="blue"')<0){try{java.toast('⚠️ 站点搜索响应超时/结果过多，请改搜更具体的书名或稍后再试')}catch(e3){}}
return parse(h);})()

