function BP_ST(u){u=String(u||'');var i=u.length;while(i>0&&u.charAt(i-1)=='/'){i--}return u.substring(0,i)}
function BP_def(){return 'https://www.blpopo.vip'}
function BP_S(){try{return source}catch(e){return null}}
function BP_gv(k,d){var S=BP_S(),v='';try{if(S)v=String(S.get(k)||'')}catch(e){}
 if(!v||v=='null'||v=='undefined')return d;return v}
function BP_base(){return BP_ST(BP_gv('bp_line',BP_def()))}
function BP_NL(){return String.fromCharCode(10)}
function BP_T(s){s=String(s);try{java.longToast(s);return}catch(e){}
 try{java.toast(s);return}catch(e2){}try{java.copyText(s)}catch(e3){}}
function BP_U(){try{java.reLoginView();return}catch(e){}try{java.reUiView()}catch(e2){}}
function BP_lines(){var v=BP_gv('bp_lines',''),a=[];
 if(v){var p=v.split(',');for(var i=0;i<p.length;i++)if(p[i]&&a.indexOf(p[i])<0)a.push(p[i])}
 if(!a.length)a=['https://www.blpopo.vip','https://blpopo.vip'];
 return a}
function BP_key(u){return 'bp_sp_'+String(u||'').replace(/[^a-z0-9]/gi,'').substring(0,24)}
function BP_pub(){return BP_ST(BP_gv('bp_pub','https://www.blpopo.com'))}
function BP_fetch(){
 BP_T('⏳ 正在从发布页获取网址路线，请稍候...');
 var v='';try{v=String((typeof result!=='undefined'&&result)?result.get('发布页'):'')}catch(e){}
 if(v&&v.indexOf('http')===0){try{BP_S().put('bp_pub',BP_ST(v))}catch(e2){}}
 var h='';try{h=String(java.ajax(BP_pub()+',{"timeout":8000}'))}catch(e){}
 if(h.length<1000)try{h=String(java.ajax('https://www.blpopo.vip,{"timeout":8000}'))}catch(e3){}
 var found=[],re=/https?:\/\/(?:www\.|m\.)?blpopo\.(?:com|vip)/gi,m;
 while((m=re.exec(h))!==null){var u=m[0].replace(/^http:\/\//,'https://');
 if(u.indexOf('m.blpopo.com')>=0||u.indexOf('www.blpopo.com')>=0)continue;
 if(found.indexOf(u)<0)found.push(u)}
 var all=BP_lines();for(var i=0;i<found.length;i++)if(all.indexOf(found[i])<0)all.push(found[i]);
 try{BP_S().put('bp_lines',all.join(','))}catch(e4){}
 BP_U();
 if(!all.length){BP_T('❌ 发布页未解析到可用网址，请在「线路」框手动输入');return ''}
 BP_T('✅ 从发布页获取 '+all.length+' 条线路：'+BP_NL()+all.join(BP_NL())+BP_NL()+'点「测速全部线路」查看延时');
 return all.join(',')}
function BP_speed(){
 BP_T('⏳ 正在逐条测速，请稍候...');
 var ls=BP_lines(),msg='',best='',bm=99999999;
 for(var i=0;i<ls.length;i++){var t0=Date.now(),ms='超时',len=0;
  try{var b=String(java.ajax(ls[i]+',{"timeout":6000}'));len=b.length;
   if(len>3000){ms=(Date.now()-t0)+'ms';if(Date.now()-t0<bm){bm=Date.now()-t0;best=ls[i]}}
   else ms='内容异常'}catch(e){ms='失败'}
  try{BP_S().put(BP_key(ls[i]),ms)}catch(e2){}
  msg+=BP_NL()+ls[i].replace(/^https?:\/\//,'')+'  '+ms}
 if(best){var k=BP_key(best);try{BP_S().put(k,'⚡'+BP_S().get(k))}catch(e3){}}
 try{BP_S().put('bp_speed_ts',String(Date.now()))}catch(e4){}
 BP_U();BP_T('📶 线路测速：'+msg+BP_NL()+'最快：'+(best||'无可用'));return msg}
function BP_pick(u){
 u=BP_ST(u);if(u.indexOf('http')!==0)u='https://'+u;
 try{BP_S().put('bp_line',u);BP_S().put('bp_line_ts',String(Date.now()))}catch(e){}
 BP_U();BP_T('✅ 已切换线路：'+u);return u}
function BP_manual(){
 var v='';try{v=String((typeof result!=='undefined'&&result)?result.get('线路'):'').trim()}catch(e){}
 if(!v){BP_T('请先在「线路」框输入网址');return ''}
 return BP_pick(v)}
function BP_default(){BP_pick(BP_def())}
function BP_check(){
 BP_T('⏳ 正在检查站点状态...');
 var t0=Date.now(),b='';try{b=String(java.ajax(BP_base()+',{"timeout":6000}'))}catch(e){}
 var ms=Date.now()-t0;
 if(b.indexOf('BL小说')<0)BP_T('❌ 当前线路不可用（'+ms+'ms），可点线路按钮切换');
 else BP_T('✅ 本站免登录，线路可达（'+ms+'ms）：'+BP_base());
 return b.length>3000?'ok':'fail'}
function BP_status(){
 var ts='';try{ts=String(BP_S().get('bp_speed_ts')||'0')}catch(e){}
 var when=ts&&ts!='0'?new Date(Number(ts)).toLocaleString():'从未';
 BP_T('📡 当前线路：'+BP_base()+BP_NL()+'发布页：'+BP_pub()+BP_NL()+'线路数：'+BP_lines().length+BP_NL()+'上次测速：'+when);
 return ''}
function login(){return BP_check()}
